{"results": [{"id": "hp_doc_2b9c41145e543a8be940e4e9f55e2b0d34241691dea2946150dc9e5774ac4815", "title": "Time Waits for No One: Anthology 1971–1977", "text": "Time Waits for No One: Anthology 1971–1977 is a British-only compilation album by The Rolling Stones released in 1979. It covers the period from \"Sticky Fingers\" in 1971 until \"Love You Live\" in 1977. Only two of ten single A-sides from the period are included—\"Angie\" and \"Fool to Cry\".", "score": 52.3391}, {"id": "hp_doc_5b7358da5b05e444340665209d3992d9273b93f263ce5e46fcf5a91ba69b1d80", "title": "Time Waits for No One (song)", "text": "\"Time Waits for No One\" is a song by British rock and roll band the Rolling Stones from its 1974 album \"It's Only Rock 'n Roll\". It was the first song recorded for the album.", "score": 39.6684}, {"id": "hp_doc_cd84431c0a78fea9c69b545c107c43fd0993c844c12ababf82bf6bd72333ff13", "title": "Rewind (1971–1984)", "text": "Rewind (1971–1984) is a compilation album by The Rolling Stones and was released in 1984. Coming only three years after \"Sucking in the Seventies\", the album was primarily compiled to mark the end of the band's alliance with Warner Music (in North America) and EMI (all other territories), both of whom were the distributors of Rolling Stones Records. It is the second Rolling Stones album to include a lyric sheet (after 1978's \"Some Girls\".)", "score": 24.7321}], "remaining_searches": 2}
